// Fuentes RSS (Google Noticias Colombia + Xataka)
const g = q => 'https://news.google.com/rss/search?q=' + encodeURIComponent(q + ' when:2d') + '&hl=es-419&gl=CO&ceid=CO:es-419';
return [
  { categoria: 'Ingeniería de sistemas', url: g('"ingeniería de sistemas" OR "ingeniería de software" OR programadores Colombia') },
  { categoria: 'Ingeniería de sistemas', url: g('ciberseguridad OR "desarrollo de software" OR "ciencia de datos" empleo Colombia') },
  { categoria: 'Tecnología', url: g('"inteligencia artificial" OR tecnología OR startups Colombia') },
  { categoria: 'Tecnología', url: 'https://www.xataka.com/feedburner.xml' },
  { categoria: 'Educación', url: g('educación superior OR universidades OR "Ministerio de Educación" Colombia') },
  { categoria: 'Educación', url: g('ICETEX OR "Saber Pro" OR becas universitarias Colombia') },
].map(f => ({ json: f }));

// Filtra últimas 48 h, clasifica por palabras clave, quita duplicados (igual que scraper/scraper_noticias.py)
const norm = t => (t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const CLAVES = {
  'Ingeniería de sistemas': ['ingenieria de sistemas','software','programador','programacion','desarrollador','ciberseguridad','datos','nube','cloud','algoritmo','devops'],
  'Tecnología': ['inteligencia artificial',' ia ','openai','chatgpt','tecnologia','robot','chip','startup','app','celular','google','microsoft','ciber'],
  'Educación': ['universidad','educacion','estudiante','icetex','saber pro','beca','mineducacion','colegio','docente','matricula','pregrado'],
};
const hash = s => { let h = 5381; for (const c of s) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0; return h.toString(16).padStart(8, '0'); };
const limite = Date.now() - 48 * 3600e3;
const vistos = new Set(); const out = [];
for (const it of $input.all()) {
  const n = it.json; let titulo = (n.title || '').trim(); let fuente = (n.creator || n.source || 'RSS');
  if (/news\.google\.com/.test(n.link || '') && titulo.includes(' - ')) { const i = titulo.lastIndexOf(' - '); fuente = titulo.slice(i + 3); titulo = titulo.slice(0, i); }
  const fecha = new Date(n.isoDate || n.pubDate || Date.now());
  if (isNaN(fecha) || fecha.getTime() < limite) continue;
  const texto = ' ' + norm(titulo + ' ' + (n.contentSnippet || '')) + ' ';
  const puntos = Object.fromEntries(Object.entries(CLAVES).map(([k, v]) => [k, v.filter(w => texto.includes(w)).length]));
  const cat = Object.entries(puntos).sort((a, b) => b[1] - a[1])[0];
  if (!cat || cat[1] === 0) continue;
  const clave = norm(titulo).split(/\W+/).filter(w => w.length > 3).slice(0, 8).sort().join(' ');
  if (vistos.has(clave) || vistos.has(n.link)) continue; vistos.add(clave); vistos.add(n.link);
  out.push({ json: { id: hash(n.link), titulo, url: n.link, fuente, categoria: cat[0], fecha: fecha.toISOString(), resumen: (n.contentSnippet || '').slice(0, 280) } });
}
return out.slice(0, 30);
